style.css:
/* My Melody Dreamland - Global Kawaii Style */
/* i really want this to be global */

/* Colores principales: puedes cambiarlos aquí */
:root {
    --my-pink: #ffeaf2 !important;
    --my-light-pink: #fff5f9 !important;
    --my-accent: #f4b8ce !important;
    --my-dark-pink: #d98eae !important;
    --my-text: #966d80 !important;
    --my-white: #ffffff !important;
}

/* Fondo rosa pastel */
body {
    background-color: var(--my-pink) !important;
    color: var(--my-text) !important;
    background-image:
        radial-gradient(circle, rgba(255,255,255,.8) 1px, transparent 2px),
        linear-gradient(135deg, #fff3f8, #ffe6f0, #fff0f6) !important;
    background-size: 22px 22px, 100% 100% !important;
    background-attachment: fixed !important;
}

/* Encabezados */
h1, h2, h3, h4 {
    color: #d98eae !important;
    font-weight: 700 !important;
}

/* Enlaces */
a {
    color: #df91b1 !important;
    transition: color .2s ease !important;
}

a:hover {
    color: #f2a9c5 !important;
}

/* Tarjetas y contenedores */
.card, article, section, [class*="card"] {
    border-radius: 18px !important;
    border-color: #f8cbdc !important;
}

/* Botones */
button, [role="button"], input[type="button"], input[type="submit"] {
    background: linear-gradient(135deg, #ffdce9, #f6bcd2) !important;
    color: #98677d !important;
    border: 1px solid #f4c0d4 !important;
    border-radius: 20px !important;
    transition: all .2s ease !important;
}

button:hover, [role="button"]:hover {
    background: #f8c4d9 !important;
    transform: translateY(-1px) !important;
}

/* Campos de texto */
input, textarea, select {
    background-color: #fff7fa !important;
    color: #966d80 !important;
    border: 1px solid #f3c5d7 !important;
    border-radius: 12px !important;
}

/* Imágenes */
img {
    border-radius: 12px;
}

/* Barras de desplazamiento */
::-webkit-scrollbar {
    width: 9px !important;
}

::-webkit-scrollbar-track {
    background: #fff0f6 !important;
}

::-webkit-scrollbar-thumb {
    background: #efb5cc !important;
    border-radius: 20px !important;
}

/* Selección de texto */
::selection {
    background: #f6c1d7 !important;
    color: #ffffff !important;
}
